{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Encainide, a high-transfer analogue with an aromatic amide and basic azacycle, has absolute oral bioavailability of 32±7% in normal subjects, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "The praziquantel analogue, which shares a bridged bicyclic amine and amide-like core, showed 27.2±5.4% oral bioavailability even in patients with hepatic impairment, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Solifenacin, a high-transfer analogue containing a bicyclic amine and carbamate, has absolute oral bioavailability of 88% in healthy volunteers, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Suvorexant, which contains a bridged bicyclic amine and amide/heteroaryl framework, has mean oral bioavailability of 82% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Celecoxib, a sulfonamide-containing analogue with poor aqueous solubility, is reported at 20–40% oral bioavailability; this is at or above the 20% threshold and does not affirmatively indicate F<20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is predicted high (F≥20%) because all high-transfer experimental analogues have measured oral bioavailability at or above 20%, mostly 27–88%, and none provide affirmative evidence of F<20%.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement exists for the exact query molecule.",
    "The sulfonylhydrazide/urea moiety is not represented by an exact analogue; its permeability and metabolic stability are inferred from related amide/sulfonyl/bicyclic-amine drugs.",
    "Celecoxib indicates solubility can limit absorption, but its reported range remains at the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

